import logging
import os
import pprint
import time
import re
from typing import Callable
import pexpect
from six.moves import queue

from taf.ul.generic_tshark_json_parser.logger_config import configure_msg_source_logger
from taf.ul.generic_tshark_json_parser.submodule_ute_common_abstract_core import message_query_builder \
    as message_query_builder
from ta_tshark_json_parser.tshark_source import TsharkSource
from taf.ul.generic_tshark_json_parser.submodule_ute_common_abstract_core.message import Message, NotFoundKey


TSHARK_COMMAND = "tshark -i eth3 -T json -f 'sctp' -l"


class GenericJsonTsharkSource(TsharkSource):
    def __init__(self,
                 tshark_command: str = 'tshark -i any -T json -l',
                 alias: str = 'default',
                 start: bool = False,
                 protocol: str = None,
                 separete_protocol_parsing: bool = None,
                 meta_data: dict = None,
                 callback: Callable = None,
                 filter_as_string: str = None,
                 filter_as_query: str = None):
        self.tshark_command = tshark_command
        self.alias = alias
        self.queue: queue.Queue = queue.Queue()
        self.callbacks: list = [self.log_callback, self.store_callback]
        if callback:
            self.callbacks.append(callback)
        self.user_callbacks = {}
        self.filter_as_string: str = filter_as_string
        self.filter_as_query: str = filter_as_query
        self.protocol: str = protocol
        self.separete_protocol_parsing: bool = separete_protocol_parsing
        self.metadata: dict = meta_data
        self.autostart: bool = start
        self.non_subclassed_logger = configure_msg_source_logger('generic_tshark_json_parser', self.alias)
        self.non_subclassed_raw_msg_logger = configure_msg_source_logger('generic_tshark_json_parser',
                                                                         f"{self.alias}_messages")
        if self.protocol is not None and self.separete_protocol_parsing is not None:
            raise Exception('Options "protocol" and "separete_protocol_parsing" are exclusive, select one of them')
        self.filter = self._generate_filter()
        self.records: list = []
        self.paused = False
        if self.autostart is True:
            self.start_source()

    def get_unique_logger_name(self):
        return f'source_alias_{self.alias}'

    def clear_reccords(self):
        self.records: list = []

    def log_callback(self, record):
        self.non_subclassed_raw_msg_logger.debug(f'\n{pprint.pformat(record)}')

    def store_callback(self, record):
        self.records.append(record)
        self.non_subclassed_logger.info(f'Stored new record, store size: {len(self.records)}')

    def add_callback(self, callback_name, callback_func):
        assert callback_name not in self.user_callbacks, f'Callback {callback_name} already exists'
        self.user_callbacks[callback_name] = callback_func
        self.non_subclassed_logger.info(f'Callback {callback_name} added')

    def remove_callback(self, callback_name):
        assert callback_name in self.user_callbacks, f'Callback {callback_name} does not exist'
        del self.user_callbacks[callback_name]
        self.non_subclassed_logger.info(f'Callback {callback_name} removed')

    def _generate_filter(self):
        if self.filter_as_query is not None and self.filter_as_string is not None:
            raise Exception('Options "filter_as_string" and "filter_as_query" are exclusive, select of them')
        if self.filter_as_string:

            def str_filter(record):
                try:
                    if len(record.get_all_values_by_key(self.filter_as_string)) == 0:
                        return False
                    else:
                        return True
                except NotFoundKey:
                    return False
            self.non_subclassed_logger.debug(f'Generated filter based on string: {self.filter_as_string}')
            return str_filter
        if self.filter_as_query:
            qeury = [self.generate_query_function(self.filter_as_query)]

            def query_filter(record):
                return qeury[0](record)

            self.non_subclassed_logger.debug(f'Generated filter as query: {self.filter_as_query}')
            return query_filter
        return None

    @staticmethod
    def generate_query_function(string_query):
        func = message_query_builder.message_query_parser().parse(input=string_query)['action_result']
        func.string_query = string_query
        return func

    def start_source(self) -> None:
        # json_protocol_subs = [('\.', '_')]
        assert self.tshark_command, 'tshark_command option must be set'

        super(GenericJsonTsharkSource, self).__init__(queue=self.queue,
                                                      layer=self.protocol,
                                                      # json_protocol_subs=json_protocol_subs,
                                                      duplicated_keys_handler='as_list')
        self.non_subclassed_logger.debug('{}: Tshark started.'.format(self.alias))

    def pause_source(self) -> None:
        """
        Source is still running, but all received records are dropped and not processed by callbacks.
        Could be used to not store unneccesary messages when not neeeded.
        :return:
        """
        if hasattr(self, 'is_running'):
            if not self.paused:
                self.paused = True
        else:
            self.non_subclassed_logger.debug('Source not paused as it is not running')

    def play_source(self) -> None:
        """
        Restore callback processing when source was paused
        :return:
        """
        if self.paused is True:
            self. paused = False
        else:
            print('Source was not paused at first place, nothing to do')

    def stop_source(self) -> None:
        if hasattr(self, 'is_running'):
            self.stop()
        else:
            self.non_subclassed_logger.debug('Source not started, nothing to stop')

    def set_tshark_command(self, tshark_command: str) -> None:
        self.tshark_command = tshark_command

    def set_filter_as_string(self, filter_as_string: str) -> None:
        self.filter_as_string = filter_as_string
        assert self.filter_as_query is None, 'filter_as_query has already been set for source'
        self.filter = self._generate_filter()

    def set_filter_as_query(self, filter_as_query: str) -> None:
        self.filter_as_query = filter_as_query
        assert self.filter_as_string is None, 'filter_as_string has already been set for source'
        self._generate_filter()

    def set_protocol(self, protocol: str) -> None:
        if self.protocol is not None and self.separete_protocol_parsing is not None:
            raise Exception('Options "protocol" and "separete_protocol_parsing" are exclusive, select one of them')
        self.protocol = protocol

    def set_meta_data(self, meta_data: dict) -> None:
        pass

    def set_divide_protocols(self) -> None:
        if self.protocol is not None and self.separete_protocol_parsing is not None:
            raise Exception('Options "protocol" and "separete_protocol_parsing" are exclusive, select one of them')
        self.separete_protocol_parsing = True

    def get_tshark_command(self) -> str:
        """ to be added """
        return self.tshark_command

    def _generate_meta_data(self, record: dict) -> dict:
        meta = {}
        return meta

    def process_data_record(self, data_record: dict) -> dict:
        """ to be added """
        if self.protocol:
            protocols = data_record['_source']['layers']
            for protocol_name in sorted(protocols.keys()):
                if self.protocol in protocol_name:
                    records: list = [protocols[protocol_name]]
                    self.non_subclassed_logger.debug(f'Filtered record over protocol: {self.protocol}')

        else:
            if self.separete_protocol_parsing:
                protocols = data_record['_source']['layers']
                records: list = []
                for protocol_name in sorted(protocols.keys()):
                    records.append(protocols[protocol_name])
                self.non_subclassed_logger.debug(f'Created {len(records)} from single packet'
                                                 f' matching received protocols')

            else:
                records: list = [data_record['_source']]
        records_as_message = self.convert_record_to_messages(data_record, records)
        records_as_message = self.filter_records(records_as_message)
        basic_and_user_callbacks = self.callbacks + list(self.user_callbacks.values())
        if len(records_as_message) and len(basic_and_user_callbacks) and self.paused is False:
            for callback in basic_and_user_callbacks:
                for record_as_message in records_as_message:
                    callback(record_as_message)
        return data_record

    def convert_record_to_messages(self, data_record, records):
        records_as_message = []
        for record in records:
            records_as_message.append(Message(record, self._generate_meta_data(data_record)))
        return records_as_message

    def filter_records(self, records_as_message):
        if not self.filter:
            self.non_subclassed_logger.debug('Filtering record is disabled')
            return records_as_message
        records_as_message_filtered = []
        for record_as_message in records_as_message:
            if self.filter(record_as_message):
                records_as_message_filtered.append(record_as_message)
                self.non_subclassed_logger.debug('Record matched filter: {}'
                                                 .format(self.filter_as_query if self.filter_as_query is not None
                                                         else self.filter_as_string))
        self.non_subclassed_logger.debug(f'Returning filtered: {len(records_as_message_filtered)} '
                                         f'out of total {len(records_as_message)} records')
        return records_as_message_filtered

    def get_opened_connection(self) -> pexpect.spawn:
        """ to be added """
        return self.get_opened_connection_local()


if __name__ == "__main__":
    a = GenericJsonTsharkSource(tshark_command=TSHARK_COMMAND,
                                # callback=pprint.pprint,
                                # filter_as_query='sctp.chunk_type eq "1"',
                                # filter_as_query='length(sctp.port) eq 2',
                                # filter_as_query='sctp.chunk_type_tree contains (sctp.chunk_bit_1 eq "0")',
                                # filter_as_query='ip.dst eq "10.0.1.2" or ip.dst eq "10.0.1.1"',
                                protocol='sctp',
                                start=True)
    print('Exit by Ctrl-C')
    while a.is_running.is_set():
        try:
            time.sleep(1)
        except KeyboardInterrupt:
            try:
                a.stop_source()
            except OSError:
                pass
